import mworks.sysplorer as ModelingPy
names = sorted([name for name in dir(ModelingPy) if any(key.lower() in name.lower() for key in [
    'Animation','Camera','View','AVI','Video','Movie','Export','Record','Result','Plot','Zoom','Pan','Rotate','Perspective','Scene'
])])
info = {}
for name in names:
    obj = getattr(ModelingPy, name)
    doc = getattr(obj, '__doc__', '')
    info[name] = doc[:600] if isinstance(doc, str) else repr(doc)
RUN_SCRIPT_RESULT = {'names': names, 'docs': info}
